import{_ as a,o as t,c as i,a0 as n}from"./chunks/framework.DB31oXgM.js";const p=JSON.parse('{"title":"ADR 003: Relational Persistence, Telemetry Partitioning & Redis Caching","description":"","frontmatter":{},"headers":[],"relativePath":"adr/003-persistence-and-partitioning.md","filePath":"adr/003-persistence-and-partitioning.md"}'),r={name:"adr/003-persistence-and-partitioning.md"};function s(o,e,l,c,d,u){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-003-relational-persistence-telemetry-partitioning-redis-caching" tabindex="-1">ADR 003: Relational Persistence, Telemetry Partitioning &amp; Redis Caching <a class="header-anchor" href="#adr-003-relational-persistence-telemetry-partitioning-redis-caching" aria-label="Permalink to &quot;ADR 003: Relational Persistence, Telemetry Partitioning &amp; Redis Caching&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The game server produces high-frequency input streams (60 events/sec per player) and requires low-latency matchmaking pools (&lt; 5ms queue operations) alongside durable match records and immutable security audit logs.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>PostgreSQL 16</strong>: Relational storage for users, matches, sessions, and append-only audit logs. High-volume <code>frame_input_logs</code> and telemetry events are partitioned by month.</li><li><strong>Redis 7.2</strong>: In-memory sorted sets for low-latency MMR matchmaking queues, ephemeral room leases (TTL 5 minutes), presence tracking, and distributed rate-limiting counters.</li><li><strong>Audit Log Immutability</strong>: Database constraints enforce append-only rules for non-superuser database roles.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Hot-path matchmaking queries resolve in $O(\\log N)$ in memory.</li><li>Telemetry table bloat is managed via partition pruning.</li></ul>',9)])])}const h=a(r,[["render",s]]);export{p as __pageData,h as default};
